import{_ as n,c as s,o as e,am as t}from"./chunks/framework.83COwwOK.js";const h=JSON.parse('{"title":"CustomVina：编写 Pogget 个性化预设","description":"","frontmatter":{"prev":{"text":"Pogget","link":"/docs/pogget/index"},"next":{"text":"组件编组","link":"/docs/pogget/group"}},"headers":[],"relativePath":"docs/pogget/custom-vina.md","filePath":"docs/pogget/custom-vina.md"}'),p={name:"docs/pogget/custom-vina.md"};function o(d,a,c,l,i,r){return e(),s("div",null,a[0]||(a[0]=[t(`<h1 id="customvina-编写-pogget-个性化预设" tabindex="-1">CustomVina：编写 Pogget 个性化预设 <a class="header-anchor" href="#customvina-编写-pogget-个性化预设" aria-label="Permalink to &quot;CustomVina：编写 Pogget 个性化预设&quot;">​</a></h1><p>CustomVina 是 Pogget 使用的个性化预设格式。预设文件使用 <code>.vina</code> 扩展名，由 Pogget 内置的 Vina 解析器读取，再交给收纳盒的绘制和交互代码执行。你可以只改颜色、圆角和标题，也可以声明一整棵自己的视图树。</p><p>这套格式不是网页 CSS。它没有选择器、<code>#rrggbb</code>、<code>px</code> 或 JavaScript；它更像一个带表达式的 UI 场景文件。下面会用“样式变量”的写法模拟 CSS 变量，但代码仍然是 Vina 语法。</p><p>本文按 VinaApp 当前的 <code>PoggetPersonalizationPanel.inl</code>、<code>PoggetPersonalizationRuntime.hpp</code> 和 <code>PoggetCore/Personalization</code> 实现整理；如果以后新增 slot 或 Action，以程序实际显示的 schema 为准。</p><h2 id="先做出第一个预设" tabindex="-1">先做出第一个预设 <a class="header-anchor" href="#先做出第一个预设" aria-label="Permalink to &quot;先做出第一个预设&quot;">​</a></h2><h3 id="_1-从设置面板创建" tabindex="-1">1. 从设置面板创建 <a class="header-anchor" href="#_1-从设置面板创建" aria-label="Permalink to &quot;1. 从设置面板创建&quot;">​</a></h3><ol><li>打开一个收纳盒的菜单，选择 <strong>个性化</strong>。</li><li>展开 <strong>高级</strong>。面板标题会显示“自定义 · 编写样式”。</li><li>选择 <strong>新建预设</strong>，填写预设名称。</li><li>选择创建方式： <ul><li><strong>复制自</strong>：复制一份完整的当前样式，之后基础预设的修改不会影响它。</li><li><strong>依赖自</strong>：只保存对某个独立预设的修改，适合做小幅改色或加一个按钮。</li></ul></li><li>对下面的第一个例子，选择 <strong>依赖自</strong>，基础预设选 <code>Pogget_Std</code>，创建一个名为 <code>MyFirstStyle</code> 的预设。</li><li>在高级编辑器中点 <strong>外部打开</strong>，用文本编辑器修改；回到 Pogget 后点 <strong>重新加载</strong>，确认效果，再点 <strong>应用并保存</strong>。</li></ol><p>面板中的 <strong>属性作用域</strong> 还分为 <strong>独立属性</strong> 和 <strong>全局属性</strong>。独立属性只写当前收纳盒；全局属性写入全局个性化配置，修改完成后点 <strong>同步更改</strong>，让使用全局作用域的收纳盒重新加载。第一次写样式时先使用独立属性，确认外观后再同步到全局。</p><p>预设文件位于数据目录的 <code>Presets\\Personalization</code> 下：</p><ul><li>普通安装通常是 <code>%LOCALAPPDATA%\\Vilinko\\Pogget\\Presets\\Personalization</code>；</li><li>便携模式是 <code>Pogget.exe</code> 同目录的 <code>.pogget_config\\Presets\\Personalization</code>。</li></ul><p>也可以在 <strong>管理预设</strong> 中直接打开这个文件夹。文件名就是预设名加上 <code>.vina</code>，例如 <code>MyFirstStyle.vina</code>。</p><h3 id="_2-先从一个安全的小改动开始" tabindex="-1">2. 先从一个安全的小改动开始 <a class="header-anchor" href="#_2-先从一个安全的小改动开始" aria-label="Permalink to &quot;2. 先从一个安全的小改动开始&quot;">​</a></h3><p>复制下面的代码到新预设中。它保留基础预设的全部内容，只在标题区域增加一个小标签。这个例子使用依赖模式，所以保留第一行 <code>Preset</code> 声明：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Preset { dependsOn: &quot;Pogget_Std&quot; }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>FirstBadge {</span></span>
<span class="line"><span>  view {</span></span>
<span class="line"><span>    type: &quot;group&quot;,</span></span>
<span class="line"><span>    interaction: &quot;title&quot;,</span></span>
<span class="line"><span>    z: 10,</span></span>
<span class="line"><span>    x: 16,</span></span>
<span class="line"><span>    y: 8,</span></span>
<span class="line"><span>    width: 110,</span></span>
<span class="line"><span>    height: 28,</span></span>
<span class="line"><span>    Badge {</span></span>
<span class="line"><span>      type: &quot;rect&quot;,</span></span>
<span class="line"><span>      width: 110,</span></span>
<span class="line"><span>      height: 28,</span></span>
<span class="line"><span>      radius: 14,</span></span>
<span class="line"><span>      background: rgb(28, 116, 154),</span></span>
<span class="line"><span>      fillOpacity: 0.92,</span></span>
<span class="line"><span>      border: 1,</span></span>
<span class="line"><span>      borderColor: \${pogget.theme.white},</span></span>
<span class="line"><span>      borderOpacity: 0.22</span></span>
<span class="line"><span>    },</span></span>
<span class="line"><span>    Text {</span></span>
<span class="line"><span>      type: &quot;text&quot;,</span></span>
<span class="line"><span>      x: 10,</span></span>
<span class="line"><span>      y: 6,</span></span>
<span class="line"><span>      width: 90,</span></span>
<span class="line"><span>      height: 18,</span></span>
<span class="line"><span>      label: &quot;CustomVina&quot;,</span></span>
<span class="line"><span>      textLiteral: true,</span></span>
<span class="line"><span>      textSize: 12,</span></span>
<span class="line"><span>      color: \${pogget.theme.white},</span></span>
<span class="line"><span>      font: &quot;Segoe UI&quot;,</span></span>
<span class="line"><span>      align: &quot;center&quot;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><code>interaction: &quot;title&quot;</code> 让这个元素跟随标题的隐藏、折叠和向上展开状态；<code>z: 10</code> 把它放到标题控件上方。保存后如果语法有问题，Pogget 会显示行号和列号，原来的最后一个有效预设会继续工作。</p><h2 id="复制和继承-依赖-有什么不同" tabindex="-1">复制和继承（依赖）有什么不同 <a class="header-anchor" href="#复制和继承-依赖-有什么不同" aria-label="Permalink to &quot;复制和继承（依赖）有什么不同&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>文件里保存什么</th><th>基础预设变化后</th><th>适合什么情况</th></tr></thead><tbody><tr><td>复制自</td><td>完整、独立的有效样式</td><td>不跟随</td><td>想把当前外观冻结下来，再长期独立修改</td></tr><tr><td>依赖自</td><td><code>Preset { dependsOn: &quot;基础名&quot; }</code> 加属性覆盖和新组件</td><td>会跟随基础预设</td><td>只想改几项，或者给标准样式加装饰</td></tr></tbody></table><p>依赖预设只支持一个独立基础预设。不能依赖另一个已经依赖别人的预设，也不能用差异文件删除基础组件。匹配到同名组件后，同路径的属性会覆盖；新组件和新子节点会按声明顺序追加。</p><p>独立复制的文件不需要 <code>Preset</code> 块；它必须包含自己要使用的完整组件。把带 <code>Preset</code> 的差异代码保存成独立副本会被当作依赖预设处理。</p><p>例如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Preset { dependsOn: &quot;Pogget_Std&quot; }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 只覆盖 Panel 的一个属性</span></span>
<span class="line"><span>Panel { width: 480 }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 新组件会追加到合成后的视图树</span></span>
<span class="line"><span>CornerMark {</span></span>
<span class="line"><span>  view { type: &quot;rect&quot;, x: 8, y: 8, width: 6, height: 6, radius: 3, background: rgb(255, 170, 0) }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>依赖模式下，编辑器显示和保存的是差异文件；Pogget 在加载、保存和热更新时合成完整场景。外部编辑基础文件时，依赖预设也会重新计算。若你需要完全不受基础预设更新影响，请使用 <strong>复制自</strong>。</p><h2 id="vina-文件的基本写法" tabindex="-1">Vina 文件的基本写法 <a class="header-anchor" href="#vina-文件的基本写法" aria-label="Permalink to &quot;Vina 文件的基本写法&quot;">​</a></h2><h3 id="块、属性和逗号" tabindex="-1">块、属性和逗号 <a class="header-anchor" href="#块、属性和逗号" aria-label="Permalink to &quot;块、属性和逗号&quot;">​</a></h3><p>最外层是一个或多个组件块。块里可以放属性，也可以放子块。属性使用 <code>名称: 值</code>，同级成员之间用逗号分隔，最后一个成员后可以保留逗号。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Card {</span></span>
<span class="line"><span>  vars {</span></span>
<span class="line"><span>    padding: 16,</span></span>
<span class="line"><span>    radius: 12</span></span>
<span class="line"><span>  },</span></span>
<span class="line"><span>  view {</span></span>
<span class="line"><span>    type: &quot;rect&quot;,</span></span>
<span class="line"><span>    x: \${vars.padding},</span></span>
<span class="line"><span>    y: \${vars.padding},</span></span>
<span class="line"><span>    width: \${pogget.width} - \${vars.padding} * 2,</span></span>
<span class="line"><span>    height: 48,</span></span>
<span class="line"><span>    radius: \${vars.radius},</span></span>
<span class="line"><span>    background: rgb(32, 40, 55)</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>块名和属性名建议使用英文、数字、下划线和点，并且同一层不能重名。字符串建议使用双引号。可以使用 <code>//</code> 或 <code>/* ... */</code> 注释。文件请保存为 UTF-8。</p><h3 id="引用和表达式" tabindex="-1">引用和表达式 <a class="header-anchor" href="#引用和表达式" aria-label="Permalink to &quot;引用和表达式&quot;">​</a></h3><p>引用写成 <code>\${...}</code>。常用的宿主输入包括：</p><table tabindex="0"><thead><tr><th>引用</th><th>含义</th></tr></thead><tbody><tr><td><code>\${pogget.width}</code> / <code>\${pogget.height}</code></td><td>收纳盒当前尺寸，单位是 DIP</td></tr><tr><td><code>\${pogget.title}</code></td><td>标题文字</td></tr><tr><td><code>\${pogget.isListView}</code></td><td>是否为列表视图</td></tr><tr><td><code>\${pogget.collapsed}</code> / <code>\${pogget.upward}</code></td><td>是否折叠、是否向上展开</td></tr><tr><td><code>\${pogget.locked}</code></td><td>是否锁定布局</td></tr><tr><td><code>\${pogget.mode}</code> / <code>\${pogget.frame}</code></td><td>当前渲染层和透明边框模式</td></tr><tr><td><code>\${pogget.theme.white}</code> / <code>\${pogget.theme.midnight}</code> / <code>\${pogget.theme.accent}</code></td><td>当前主题颜色</td></tr></tbody></table><p>在组件内部可以使用 <code>\${self.width}</code>、<code>\${parent.width}</code>、<code>\${ui.field.value}</code> 和 <code>\${vars.name}</code>。表达式支持：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>+ - * / % ^</span></span>
<span class="line"><span>== != &lt; &lt;= &gt; &gt;= &amp;&amp; || ! ?:</span></span>
<span class="line"><span>min max clamp abs floor ceil round sqrt hypot trunc f32 pow</span></span>
<span class="line"><span>rgb fade red green blue average</span></span></code></pre></div><p>时间属性可以写 <code>160ms</code>，它等于 0.16 秒。表达式没有循环、脚本或任意函数调用；动作也只能调用 Pogget 已注册的白名单。</p><p>颜色使用 Windows <code>COLORREF</code> 整数。最容易读的写法是 <code>rgb(红, 绿, 蓝)</code>，例如 <code>rgb(30, 144, 255)</code>；<code>fade(color, amount)</code> 可按亮度方向调整颜色。</p><h2 id="可以使用哪些样式" tabindex="-1">可以使用哪些样式 <a class="header-anchor" href="#可以使用哪些样式" aria-label="Permalink to &quot;可以使用哪些样式&quot;">​</a></h2><h3 id="通用视图图元" tabindex="-1">通用视图图元 <a class="header-anchor" href="#通用视图图元" aria-label="Permalink to &quot;通用视图图元&quot;">​</a></h3><table tabindex="0"><thead><tr><th><code>type</code></th><th>用途</th><th>常用属性</th></tr></thead><tbody><tr><td><code>group</code></td><td>只负责组织子节点</td><td><code>x</code>、<code>y</code>、<code>width</code>、<code>height</code>、<code>clip</code>、<code>z</code></td></tr><tr><td><code>rect</code> / <code>rectangle</code> / <code>button</code> / <code>container</code></td><td>圆角矩形、边框和阴影</td><td><code>background</code>、<code>radius</code>、<code>border</code>、<code>shadowOpacity</code></td></tr><tr><td><code>solid</code></td><td>实色矩形</td><td><code>background</code>、<code>fillOpacity</code></td></tr><tr><td><code>texture</code></td><td>带纹理的表面</td><td><code>texture</code>、<code>background</code>、<code>radius</code></td></tr><tr><td><code>glass</code></td><td>玻璃高光材质</td><td><code>glassRenderer</code>、<code>glassOpacity</code>、<code>glassBorder</code></td></tr><tr><td><code>text</code></td><td>普通文字</td><td><code>label</code>、<code>font</code>、<code>textSize</code>、<code>color</code>、<code>align</code></td></tr><tr><td><code>icon</code></td><td>用字体绘制图标</td><td><code>icon</code>、<code>font</code>、<code>textSize</code>、<code>color</code></td></tr><tr><td><code>image</code></td><td>WIC、Shell 或资源图片</td><td><code>source</code>、<code>imageRenderer</code>、<code>imageFit</code></td></tr><tr><td><code>content</code></td><td>宿主提供的同步内容资源</td><td><code>source</code>、<code>contentScale</code></td></tr></tbody></table><p><code>rect</code> 和 <code>glass</code> 默认会参与绘制；<code>group</code> 本身不画背景。要让子节点不越出圆角区域，可以在父组上设置 <code>clip: true</code> 和 <code>clipRadius</code>。</p><h3 id="pogget-已接入的场景范围" tabindex="-1">Pogget 已接入的场景范围 <a class="header-anchor" href="#pogget-已接入的场景范围" aria-label="Permalink to &quot;Pogget 已接入的场景范围&quot;">​</a></h3><p>标准预设已经把收纳盒拆成多个可替换阶段。常用范围如下：</p><table tabindex="0"><thead><tr><th>范围</th><th>slot 或组件</th><th>典型用途</th></tr></thead><tbody><tr><td>整体背景</td><td><code>containerFrame</code></td><td>背景、透明层、玻璃和最终边框</td></tr><tr><td>标题区</td><td><code>titleSurface</code>、<code>titleCollapse</code>、<code>titleMore</code>、<code>titlePin</code>、<code>titleTag</code></td><td>标题表面、折叠/菜单/固定按钮、颜色标签</td></tr><tr><td>标签页和搜索</td><td><code>titleTab</code>、<code>titleSearchSurface</code>、<code>titleSearchInput</code></td><td>标签页分配、搜索框皮肤和布局</td></tr><tr><td>文件项目</td><td><code>fileIconSurface</code>、<code>fileIconContent</code>、<code>fileIconText</code>、<code>filePreview</code>、<code>fileIconMotion</code></td><td>图标表面、缩略图、文件名、预览和动画</td></tr><tr><td>内联内容</td><td><code>inlineContentSurface</code>、<code>inlineContentSnapshot</code>、<code>inlineNavigationSurface</code></td><td>文件夹/编辑器内联视图及工具栏</td></tr><tr><td>编辑器与分页</td><td><code>markdownEditorSurface</code>、<code>markdownEditorContent</code>、<code>markdownEditorCaret</code>、<code>pageIndicatorSurface</code> 等</td><td>Markdown 编辑器皮肤、滚动条、分页点</td></tr></tbody></table><p>缺少 slot 的旧预设会保留对应的原生绘制。需要完整接管的阶段必须声明完整的 slot 组合；例如内联导航需要 surface 加上返回、主页、保存、打开、搜索五个按钮 slot，声明不完整时会回退整套原生工具栏。这样可以先从一个普通 <code>view</code> 组件开始，不必一次重写整个收纳盒。</p><h3 id="只调整原生标题控件的位置" tabindex="-1">只调整原生标题控件的位置 <a class="header-anchor" href="#只调整原生标题控件的位置" aria-label="Permalink to &quot;只调整原生标题控件的位置&quot;">​</a></h3><p>如果只需要调整标签和菜单的位置，可以使用一个 <code>pogget.native.Header</code> 兼容组件。它改变的是布局，不会替换原生点击、长按和菜单行为；同一预设只能声明一个 Header。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HeaderLayout {</span></span>
<span class="line"><span>  view {</span></span>
<span class="line"><span>    type: &quot;pogget.native.Header&quot;,</span></span>
<span class="line"><span>    tagAlign: &quot;center&quot;,</span></span>
<span class="line"><span>    tagY: 0,</span></span>
<span class="line"><span>    tagHeight: 24,</span></span>
<span class="line"><span>    moreX: \${pogget.width} / 2 - 7,</span></span>
<span class="line"><span>    moreY: 30</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><h2 id="把-ui-当作样式变量面板" tabindex="-1">把 <code>ui</code> 当作样式变量面板 <a class="header-anchor" href="#把-ui-当作样式变量面板" aria-label="Permalink to &quot;把 \`ui\` 当作样式变量面板&quot;">​</a></h2><p><code>ui</code> 不是 CSS，但它可以提供一个内嵌的“主题变量”面板。没有 <code>bind</code> 的字段只保存到当前预设，不会修改 Pogget 的原生设置；字段值通过 <code>\${ui.字段名.value}</code> 参与表达式。</p><p>下面的写法相当于把颜色和圆角集中成一组可编辑的 CSS 变量：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ThemeTokens {</span></span>
<span class="line"><span>  ui {</span></span>
<span class="line"><span>    Accent {</span></span>
<span class="line"><span>      label: &quot;强调色&quot;,</span></span>
<span class="line"><span>      type: &quot;number&quot;,</span></span>
<span class="line"><span>      control: &quot;color&quot;,</span></span>
<span class="line"><span>      min: 0,</span></span>
<span class="line"><span>      max: 16777215,</span></span>
<span class="line"><span>      step: 1,</span></span>
<span class="line"><span>      default: rgb(42, 169, 190)</span></span>
<span class="line"><span>    },</span></span>
<span class="line"><span>    Radius {</span></span>
<span class="line"><span>      label: &quot;圆角&quot;,</span></span>
<span class="line"><span>      type: &quot;number&quot;,</span></span>
<span class="line"><span>      control: &quot;slider&quot;,</span></span>
<span class="line"><span>      min: 0,</span></span>
<span class="line"><span>      max: 32,</span></span>
<span class="line"><span>      step: 1,</span></span>
<span class="line"><span>      default: 12</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>  },</span></span>
<span class="line"><span>  vars {</span></span>
<span class="line"><span>    accent: \${ui.Accent.value},</span></span>
<span class="line"><span>    surface: fade(\${ui.Accent.value}, -35),</span></span>
<span class="line"><span>    radius: \${ui.Radius.value}</span></span>
<span class="line"><span>  },</span></span>
<span class="line"><span>  view {</span></span>
<span class="line"><span>    type: &quot;group&quot;,</span></span>
<span class="line"><span>    width: \${pogget.width},</span></span>
<span class="line"><span>    height: \${pogget.height},</span></span>
<span class="line"><span>    interaction: &quot;title&quot;,</span></span>
<span class="line"><span>    z: 9,</span></span>
<span class="line"><span>    Surface {</span></span>
<span class="line"><span>      type: &quot;rect&quot;,</span></span>
<span class="line"><span>      x: 16,</span></span>
<span class="line"><span>      y: 8,</span></span>
<span class="line"><span>      width: \${pogget.width} - 32,</span></span>
<span class="line"><span>      height: 34,</span></span>
<span class="line"><span>      radius: \${vars.radius},</span></span>
<span class="line"><span>      background: \${vars.surface},</span></span>
<span class="line"><span>      fillOpacity: 0.88,</span></span>
<span class="line"><span>      border: 1,</span></span>
<span class="line"><span>      borderColor: \${vars.accent},</span></span>
<span class="line"><span>      borderOpacity: 0.45</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>这里的 <code>ThemeTokens</code> 会在高级面板里显示两个控件；改动控件时，依赖它们的视图会重新计算。不要写成 <code>background: #2aa9be</code> 或 <code>padding: 12px</code>，这两种 CSS 写法不属于 CustomVina 语法。</p><h2 id="从零写一个可交互的按钮" tabindex="-1">从零写一个可交互的按钮 <a class="header-anchor" href="#从零写一个可交互的按钮" aria-label="Permalink to &quot;从零写一个可交互的按钮&quot;">​</a></h2><h3 id="_1-用-ui-声明可调整的位置" tabindex="-1">1. 用 <code>ui</code> 声明可调整的位置 <a class="header-anchor" href="#_1-用-ui-声明可调整的位置" aria-label="Permalink to &quot;1. 用 \`ui\` 声明可调整的位置&quot;">​</a></h3><p><code>ui</code> 支持 <code>slider</code>、<code>number</code>、<code>switch</code>、<code>choice</code>/<code>select</code>、<code>text</code>、<code>color</code>、<code>button</code> 和 <code>font</code>。数字控件至少要有 <code>default</code>、<code>min</code>、<code>max</code>、<code>step</code>。</p><h3 id="_2-用-view-显示按钮" tabindex="-1">2. 用 <code>view</code> 显示按钮 <a class="header-anchor" href="#_2-用-view-显示按钮" aria-label="Permalink to &quot;2. 用 \`view\` 显示按钮&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ViewToggle {</span></span>
<span class="line"><span>  ui {</span></span>
<span class="line"><span>    Left {</span></span>
<span class="line"><span>      label: &quot;按钮 X 坐标&quot;,</span></span>
<span class="line"><span>      type: &quot;number&quot;,</span></span>
<span class="line"><span>      control: &quot;slider&quot;,</span></span>
<span class="line"><span>      min: 0,</span></span>
<span class="line"><span>      max: 300,</span></span>
<span class="line"><span>      step: 1,</span></span>
<span class="line"><span>      default: 12</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>  },</span></span>
<span class="line"><span>  view {</span></span>
<span class="line"><span>    type: &quot;button&quot;,</span></span>
<span class="line"><span>    interaction: &quot;title&quot;,</span></span>
<span class="line"><span>    x: \${ui.Left.value},</span></span>
<span class="line"><span>    y: 8,</span></span>
<span class="line"><span>    width: 28,</span></span>
<span class="line"><span>    height: 28,</span></span>
<span class="line"><span>    z: 10,</span></span>
<span class="line"><span>    radius: 6,</span></span>
<span class="line"><span>    background: \${pogget.theme.midnight},</span></span>
<span class="line"><span>    color: \${pogget.theme.white},</span></span>
<span class="line"><span>    font: &quot;Font Awesome 6 Free Solid&quot;,</span></span>
<span class="line"><span>    icon: \${pogget.isListView} ? &quot;\\uf03a&quot; : &quot;\\uf00a&quot;,</span></span>
<span class="line"><span>    action: pogget.action.view.toggle,</span></span>
<span class="line"><span>    transition: 160ms,</span></span>
<span class="line"><span>    hover { opacity: 0.75 }</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><code>hover</code> 里的属性是悬停目标，Pogget 会在 <code>transition</code> 指定的时间内插值。<code>action</code> 只写动作 ID，不写函数名、不写脚本。常用动作包括：</p><table tabindex="0"><thead><tr><th>Action</th><th>作用</th></tr></thead><tbody><tr><td><code>pogget.action.view.toggle</code></td><td>在列表和图标视图之间切换</td></tr><tr><td><code>pogget.action.view.list</code> / <code>pogget.action.view.grid</code></td><td>切换到指定视图</td></tr><tr><td><code>pogget.action.container.toggleCollapse</code></td><td>折叠或展开收纳盒</td></tr><tr><td><code>pogget.action.container.menu</code></td><td>打开收纳盒菜单</td></tr><tr><td><code>pogget.action.container.tagMenu</code></td><td>打开颜色标签菜单</td></tr><tr><td><code>pogget.action.container.pin</code></td><td>固定或取消固定</td></tr><tr><td><code>pogget.action.container.personalization</code></td><td>打开个性化面板</td></tr><tr><td><code>pogget.action.container.inlineBack</code> / <code>inlineHome</code></td><td>内联视图后退或回到主页</td></tr><tr><td><code>pogget.action.container.toggleInlineSearch</code></td><td>打开或关闭内联搜索</td></tr></tbody></table><p>完整动作集合由 Pogget 固定注册。未知 Action 会被拒绝，因此预设不能调用任意 Windows API 或执行命令。</p><h3 id="_3-正确处理点击区域" tabindex="-1">3. 正确处理点击区域 <a class="header-anchor" href="#_3-正确处理点击区域" aria-label="Permalink to &quot;3. 正确处理点击区域&quot;">​</a></h3><p>按钮的可点击区域就是有 <code>action</code> 或 <code>holdAction</code> 的视图。需要扩大命中范围时，可以设置 <code>hitPaddingX</code> 和 <code>hitPaddingY</code>；需要长按时再加 <code>holdAction</code>、<code>holdDelay</code>、<code>holdDuration</code> 和 <code>holdScale</code>。不要用一个假的变量模拟折叠状态；直接读取 <code>\${pogget.collapsed}</code>、<code>\${pogget.isListView}</code> 等宿主事实。</p><h2 id="三个可以直接改的例子" tabindex="-1">三个可以直接改的例子 <a class="header-anchor" href="#三个可以直接改的例子" aria-label="Permalink to &quot;三个可以直接改的例子&quot;">​</a></h2><h3 id="让标题变成半透明胶囊" tabindex="-1">让标题变成半透明胶囊 <a class="header-anchor" href="#让标题变成半透明胶囊" aria-label="Permalink to &quot;让标题变成半透明胶囊&quot;">​</a></h3><p>这是依赖标准预设时的最小覆盖示例。它覆盖 <code>TitleSurface</code> 的一部分属性，并保留原来的标题按钮和搜索布局：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Preset { dependsOn: &quot;Pogget_Std&quot; }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>TitleSurface {</span></span>
<span class="line"><span>  vars {</span></span>
<span class="line"><span>    style: 2,</span></span>
<span class="line"><span>    alpha: 0.78,</span></span>
<span class="line"><span>    radius: 20</span></span>
<span class="line"><span>  },</span></span>
<span class="line"><span>  view {</span></span>
<span class="line"><span>    Surface {</span></span>
<span class="line"><span>      background: \${pogget.titleColor},</span></span>
<span class="line"><span>      fillOpacity: \${vars.alpha},</span></span>
<span class="line"><span>      radius: \${vars.radius},</span></span>
<span class="line"><span>      border: 1,</span></span>
<span class="line"><span>      borderColor: \${pogget.theme.white},</span></span>
<span class="line"><span>      borderOpacity: 0.18</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>如果基础组件中同名属性是一个块而不是属性，不能用属性替换它；反过来也一样。此时应当复制完整组件再修改，或者把新内容放在自己的组件里。</p><h3 id="只给文件项目加一个悬停边框" tabindex="-1">只给文件项目加一个悬停边框 <a class="header-anchor" href="#只给文件项目加一个悬停边框" aria-label="Permalink to &quot;只给文件项目加一个悬停边框&quot;">​</a></h3><p>文件图标的宿主输入已经包含 <code>\${pogget.fileIcon.hovered}</code>、<code>\${pogget.fileIcon.selected}</code> 和 <code>\${pogget.fileIcon.x}</code> 等事实。下面的组件不会接管文件拖拽和排序，只绘制一个装饰层：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>FileHoverRing {</span></span>
<span class="line"><span>  view {</span></span>
<span class="line"><span>    type: &quot;rect&quot;,</span></span>
<span class="line"><span>    interaction: &quot;icon&quot;,</span></span>
<span class="line"><span>    z: 4,</span></span>
<span class="line"><span>    x: \${pogget.fileIcon.x} - 4,</span></span>
<span class="line"><span>    y: \${pogget.fileIcon.y} - 4,</span></span>
<span class="line"><span>    width: \${pogget.fileIcon.size} + 8,</span></span>
<span class="line"><span>    height: \${pogget.fileIcon.size} + 8,</span></span>
<span class="line"><span>    radius: 12,</span></span>
<span class="line"><span>    background: 0,</span></span>
<span class="line"><span>    fillOpacity: 0,</span></span>
<span class="line"><span>    borderOnly: true,</span></span>
<span class="line"><span>    border: 2,</span></span>
<span class="line"><span>    borderColor: \${pogget.theme.accent},</span></span>
<span class="line"><span>    borderOpacity: \${pogget.fileIcon.hovered} ? 0.8 : 0</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>文件项目的完整声明式绘制还涉及 <code>fileIconSurface</code>、<code>fileIconContent</code>、<code>fileIconText</code> 和 <code>fileIconMotion</code>。如果只是加装饰，先用独立组件；如果要重排文件名、缩略图或拖动动画，再按标准预设对应的 slot 逐步接管。</p><h3 id="用玻璃材质做一个信息卡" tabindex="-1">用玻璃材质做一个信息卡 <a class="header-anchor" href="#用玻璃材质做一个信息卡" aria-label="Permalink to &quot;用玻璃材质做一个信息卡&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GlassCard {</span></span>
<span class="line"><span>  view {</span></span>
<span class="line"><span>    type: &quot;glass&quot;,</span></span>
<span class="line"><span>    x: 18,</span></span>
<span class="line"><span>    y: \${pogget.height} - 74,</span></span>
<span class="line"><span>    width: \${pogget.width} - 36,</span></span>
<span class="line"><span>    height: 52,</span></span>
<span class="line"><span>    radius: 16,</span></span>
<span class="line"><span>    background: \${pogget.theme.midnight},</span></span>
<span class="line"><span>    glassRenderer: &quot;standard&quot;,</span></span>
<span class="line"><span>    glassBorder: 1,</span></span>
<span class="line"><span>    glassOpacity: 0.8,</span></span>
<span class="line"><span>    fillOpacity: 0.28,</span></span>
<span class="line"><span>    borderOpacity: 0.35,</span></span>
<span class="line"><span>    borderColor: \${pogget.theme.white}</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><code>glassRenderer</code> 只能写 <code>standard</code> 或 <code>liquid</code>。使用液态玻璃并自己提供指针位置时，<code>glassPointerX</code> 和 <code>glassPointerY</code> 必须同时存在；只写其中一个会被拒绝。</p><h2 id="保存、热更新和排错" tabindex="-1">保存、热更新和排错 <a class="header-anchor" href="#保存、热更新和排错" aria-label="Permalink to &quot;保存、热更新和排错&quot;">​</a></h2><h3 id="建议的修改循环" tabindex="-1">建议的修改循环 <a class="header-anchor" href="#建议的修改循环" aria-label="Permalink to &quot;建议的修改循环&quot;">​</a></h3><ol><li>先用 <strong>复制自</strong> 建一个工作副本，或者对依赖预设做很小的差异。</li><li>每次只改一个目标：颜色、尺寸、交互动作分开验证。</li><li>保存前确认逗号、括号和 <code>\${...}</code> 成对出现。</li><li>回到 Pogget 点 <strong>重新加载</strong>，分别测试普通、列表、折叠、向上展开和锁定状态。</li><li>通过后再把预设应用到全局，或把 <code>.vina</code> 文件交给其他人。</li></ol><p>外部文件变更会被定时检查，解析成功后替换当前视图；解析失败时保留最后一个有效场景，不会把半截文件直接画到窗口上。保存使用临时文件和原子替换，编辑器检测到文件已被别人修改时会要求先重新加载。</p><h3 id="常见错误" tabindex="-1">常见错误 <a class="header-anchor" href="#常见错误" aria-label="Permalink to &quot;常见错误&quot;">​</a></h3><table tabindex="0"><thead><tr><th>现象</th><th>检查方法</th></tr></thead><tbody><tr><td>“unexpected token”</td><td>属性之间是否漏了逗号；字符串是否少了引号</td></tr><tr><td>“unknown reference”</td><td>路径是否真的存在；组件内部优先使用 <code>self.</code>、<code>parent.</code>、<code>ui.</code> 或 <code>vars.</code></td></tr><tr><td>颜色报错</td><td>使用 <code>rgb(r,g,b)</code> 或 0 到 <code>16777215</code> 的整数，不能使用 <code>#RRGGBB</code></td></tr><tr><td>按钮没有反应</td><td>是否写了白名单 Action；视图是否 <code>visible</code>、<code>enabled</code> 且有正的宽高</td></tr><tr><td>新组件挡住原来的按钮</td><td>调整 <code>z</code>；标题装饰通常使用 <code>interaction: &quot;title&quot;</code> 和 <code>z: 10</code></td></tr><tr><td>修改了基础预设却没有变化</td><td>当前预设可能是复制模式；复制不会跟随基础预设</td></tr><tr><td>依赖预设加载失败</td><td><code>dependsOn</code> 必须是一个存在的独立预设名，不能写 <code>.vina</code>、路径或第二层依赖</td></tr><tr><td>文件项目绘制不完整</td><td>对应 slot 声明不完整时会回退原生绘制；先参照标准预设的完整 slot 组合</td></tr></tbody></table><h2 id="发布前检查清单" tabindex="-1">发布前检查清单 <a class="header-anchor" href="#发布前检查清单" aria-label="Permalink to &quot;发布前检查清单&quot;">​</a></h2><ul><li>[ ] 预设名不含路径分隔符、控制字符或 Windows 保留设备名。</li><li>[ ] 文件使用 UTF-8，块名和同级属性没有重复。</li><li>[ ] 所有尺寸、坐标、不透明度和颜色都在合理范围内。</li><li>[ ] 至少在图标视图、列表视图、折叠、向上展开和窄窗口下各看一次。</li><li>[ ] 每个交互元素都使用已注册的 Action，并测试移出、失焦、按下后热更新等情况。</li><li>[ ] 依赖预设只保存必要差异；需要冻结外观时改用独立复制。</li><li>[ ] 发布前保留 <code>.vina</code> 原文件和一个可回退的 <code>Pogget_Std</code> 副本。</li></ul><p>标准预设 <code>Presets\\Personalization\\Pogget_Std.vina</code> 是最完整的参考文件。遇到高级 slot 时，先复制其中同名组件，再逐项删减；这样可以保留宿主已经接好的拖动、输入、动画和资源生命周期。</p>`,81)]))}const u=n(p,[["render",o]]);export{h as __pageData,u as default};
